// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address user) public {
        vm.assume(user != address(0));
        vm.assume(user != address(c.ceoAddress()));

        // Seed the market first
        c.seedMarket{value: 1 ether}(1000000);

        // Warp to a fixed timestamp for reproducibility
        vm.warp(1000);

        // User calls getFreeKilo()
        vm.prank(user);
        c.getFreeKilo();

        // Immediately after, lastCollect[user] should be block.timestamp (1000)
        // In the buggy version, lastCollect[user] = block.timestamp + 1
        // So getDrugsSinceLastCollect should return 0 in the reference but >0 in the buggy version
        uint256 drugsSinceLastCollect = c.getDrugsSinceLastCollect(user);

        // The rule: After getFreeKilo(), no time has passed, so drugsSinceLastCollect should be 0
        assertTrue(drugsSinceLastCollect == 0, "Drugs generated immediately after getFreeKilo() should be zero");
    }
}

